 * from `middleware` to `proxy`. Do not reintroduce the old names — Next 16
 * ignores them silently and every route becomes public.
 *
10→ * This proxy only decides "is there a session cookie at all". Real
 * authorization happens in the layouts and Server Actions via `can()`; a proxy
 * cannot reach the database.
 */

const PUBLIC_PREFIXES = [
  "/",
  "/pricing",
  "/changelog",
  "/about",
20→  "/login",
  "/register",
  "/reset-password",
  "/invite",
  "/api/health",
  "/api/webhooks",
];

function isPublicPath(pathname: string): boolean {
  return PUBLIC_PREFIXES.some(
30→    (prefix) => pathname === prefix || pathname.startsWith(`${prefix}/`),
  );
}

export function proxy(request: NextRequest): NextResponse {
  const { pathname, search } = request.nextUrl;

  if (isPublicPath(pathname)) {
    return NextResponse.next();
  }
40→
  const session = request.cookies.get(SESSION_COOKIE_NAME);
  if (!session?.value) {
    const loginUrl = new URL("/login", request.url);
    loginUrl.searchParams.set("next", `${pathname}${search}`);
